/* @prim:begin 67-trace-steps */
.trace { margin: 0; }
.trace-steps { list-style: none; margin: 0; padding: 0; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: var(--sp-3, 24px); }
.trace-steps li { position: relative; display: flex; flex-direction: column; gap: 4px; padding: var(--sp-2, 16px); background: var(--surface); border: 1px solid var(--border); border-radius: var(--ds-r-md); }
.trace-steps li + li::before { content: "\2192"; position: absolute; left: calc(-1 * var(--sp-3, 24px)); width: var(--sp-3, 24px); top: 50%; transform: translateY(-50%); text-align: center; color: var(--muted); }
.trace-k { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: var(--cyan); }
.trace-v { color: var(--text); }
.trace-stop { margin: var(--sp-2, 16px) 0 0; padding-top: var(--sp-1, 8px); border-top: 1px dashed var(--muted); text-align: center; color: var(--text-secondary); }
.trace-stop strong { color: var(--text); font-weight: 600; }
@media (max-width: 640px) { .trace-steps { grid-auto-flow: row; grid-auto-columns: auto; grid-template-columns: minmax(0, 1fr); } .trace-steps li + li::before { content: "\2193"; left: 0; right: 0; width: auto; top: calc(-1 * var(--sp-3, 24px)); transform: none; height: var(--sp-3, 24px); line-height: var(--sp-3, 24px); } }
@container (max-width: 40rem) { .trace-steps { grid-auto-flow: row; grid-auto-columns: auto; grid-template-columns: minmax(0, 1fr); } .trace-steps li + li::before { content: "\2193"; left: 0; right: 0; width: auto; top: calc(-1 * var(--sp-3, 24px)); transform: none; height: var(--sp-3, 24px); line-height: var(--sp-3, 24px); } }
@media print { .trace { display: none; } }
/* @prim:end 67-trace-steps */

