function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var TS=[['Inputs','What it relies on'],['Decision','What it can\'t see'],['Outcome','The date you\'ll know']];
function kitTrace(host,n){var w=document.createElement('figure');w.className='trace';w.setAttribute('aria-label','How one decision is traced');w.innerHTML='<ol class="trace-steps">'+TS.slice(0,n).map(function(s){return '<li><span class="trace-k">'+kEsc(s[0])+'</span><span class="trace-v">'+kEsc(s[1])+'</span></li>'}).join('')+'</ol><p class="trace-stop"><strong>Agreed first:</strong> The number that would tell you to stop, set before the decision is made.</p>';host.appendChild(w);return w}
kitTrace(kSlot(),3);
STATES.forEach(function(a,i){var b=document.createElement('div');b.style.maxWidth=a[1];if(a[1]!=='100%')b.style.containerType='inline-size';kSlot(i).appendChild(b);kitTrace(b,a[0])});
